    /**
     * 取单个后台 SVG 图标（不存在时回退 settings）
     *
     * @param string $name  图标键名（见 admin_svg_icons() 数组）
     * @param string $class 开标签 class 属性值：
     *   - 默认 'svg-icon'：独立使用（16px，见 sidebar.css），与原有用法兼容；
     *   - 传空串 ''：不输出 class 属性，适用于 .btn/.icon-btn/.upload-btn 等
     *     按钮内的图标——这些场景由 .btn svg 等元素选择器统一控制尺寸与描边，
     *     若带上 svg-icon（display:block）反而会导致按钮内布局破坏；
     *   - 传自定义 class：保留原内联图标的钩子类名（如 filter-toggle-arrow 动画钩子）。
     * @return string 完整 SVG 标记
     */
    function admin_svg_icon(string $name, string $class = 'svg-icon'): string {
        $icons = admin_svg_icons();
        $svg = $icons[$name] ?? $icons['settings'];
        // 库内数据固定带 class="svg-icon"，这里按第二参数重写开标签：
        // 空串时整体移除 class 属性，其他值原样替换（内部路径无 class 属性，仅首次匹配作用于开标签）
        if ($class === 'svg-icon') {
            return $svg;
        }
        if ($class === '') {
            return preg_replace('/ class="[^"]*"/', '', $svg, 1);
        }
        return preg_replace('/ class="[^"]*"/', ' class="' . htmlspecialchars($class, ENT_QUOTES) . '"', $svg, 1);
    }
